SELECT 'schedule' AS kind,jsonb_build_object('count',count(*),'games',count(DISTINCT source_game_id),'minFetched',min(fetched_at),'maxFetched',max(fetched_at),'minUpdated',min(updated_at),'maxUpdated',max(updated_at),'newerThanOct9',count(*) FILTER(WHERE fetched_at>'2026-10-10T00:00:00Z' OR updated_at>'2026-10-10T00:00:00Z')) AS facts FROM public.roster_optimizer_team_games WHERE game_key='477' AND source_game_id BETWEEN 2026020084 AND 2026020140 UNION ALL SELECT 'audit',jsonb_build_object('job_name',job_name,'run_time',run_time,'status',status,'rows_affected',rows_affected,'details',details) FROM (SELECT * FROM public.cron_job_audit WHERE job_name ILIKE '%roster%optimizer%schedule%' AND run_time>'2026-10-13T23:00:00Z' ORDER BY run_time DESC LIMIT 4) a;